-- FUNCTION: update_updated_at()
CREATE FUNCTION __SCHEMA__.update_updated_at() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    NEW.updated_at = now();
    RETURN NEW;
END;
$$;

