    psi_max double precision,
    psi_max_dimension character varying(255),
    current_event_count integer,
    novel_rate_max double precision,
    g_stat_max double precision,
    p_value_min double precision,
    significant boolean DEFAULT false NOT NULL,
    fp_damping double precision,
    fp_rate double precision,
    needs_tuning boolean DEFAULT false NOT NULL,
    suppressed_dimensions jsonb DEFAULT '[]'::jsonb NOT NULL,
    status character varying(32) NOT NULL,
    raw_status character varying(32),
    previous_status character varying(32),
    previous_drift double precision,
    consecutive_below_recovery integer DEFAULT 0 NOT NULL,
    retraining_status character varying(32) DEFAULT 'not_required'::character varying NOT NULL,
    candidate_baseline_version bigint,
    holdout_window_start timestamp with time zone,
    holdout_window_end timestamp with time zone,
    approved_by character varying(255),
    approved_at timestamp with time zone,
    data_quality_status character varying(16) DEFAULT 'ok'::character varying NOT NULL,
