    reasons_json jsonb DEFAULT '[]'::jsonb NOT NULL,
    explanation_json jsonb DEFAULT '{}'::jsonb NOT NULL,
    computed_at timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    CONSTRAINT identity_drift_scores_dq_chk CHECK (((data_quality_status)::text = ANY ((ARRAY['ok'::character varying, 'degraded'::character varying])::text[]))),
    CONSTRAINT identity_drift_scores_drift_chk CHECK (((drift IS NULL) OR (drift >= (0.0)::double precision))),
    CONSTRAINT identity_drift_scores_drift_raw_chk CHECK (((drift_raw IS NULL) OR (drift_raw >= (0.0)::double precision))),
    CONSTRAINT identity_drift_scores_raw_status_chk CHECK (((raw_status IS NULL) OR ((raw_status)::text = ANY ((ARRAY['healthy'::character varying, 'monitor'::character varying, 'stale'::character varying, 'insufficient_data'::character varying, 'data_quality_issue'::character varying])::text[])))),
    CONSTRAINT identity_drift_scores_retraining_chk CHECK (((retraining_status)::text = ANY ((ARRAY['not_required'::character varying, 'required'::character varying, 'inspected'::character varying, 'legitimate_change'::character varying, 'suspicious_change'::character varying, 'candidate_built'::character varying, 'validated'::character varying, 'published'::character varying, 'rolled_back'::character varying])::text[]))),
    CONSTRAINT identity_drift_scores_status_chk CHECK (((status)::text = ANY ((ARRAY['healthy'::character varying, 'monitor'::character varying, 'stale'::character varying, 'insufficient_data'::character varying, 'data_quality_issue'::character varying])::text[])))
);

