-- VIEW: ispm_effective_weights
CREATE VIEW __SCHEMA__.ispm_effective_weights AS
 WITH r AS (
         SELECT r_1.rule_id,
            r_1.rule_name,
            r_1.severity,
            r_1.rule_weight,
            c.category_code,
            c.category_name,
            c.weight AS category_weight
           FROM (__SCHEMA__.ispm_rule_weights r_1
             JOIN __SCHEMA__.ispm_categories c USING (category_code))
          WHERE (r_1.enabled AND c.enabled)
        ), cats AS (
         SELECT DISTINCT r_1.category_code,
            r_1.category_weight
           FROM r r_1
        )
 SELECT category_code,
    category_name,
    category_weight,
    round((category_weight / ( SELECT sum(cats.category_weight) AS sum
           FROM cats)), 4) AS category_share,
    rule_id,
    rule_name,
    severity,
    rule_weight,
    round((rule_weight / sum(rule_weight) OVER (PARTITION BY category_code)), 4) AS rule_share,
    round((((category_weight / ( SELECT sum(cats.category_weight) AS sum
           FROM cats)) * rule_weight) / sum(rule_weight) OVER (PARTITION BY category_code)), 4) AS effective_share,
    round((((category_weight / ( SELECT max(cats.category_weight) AS max
           FROM cats)) * rule_weight) / max(rule_weight) OVER (PARTITION BY category_code)), 4) AS risk_factor,
    round((((((
        CASE severity
            WHEN 'Critical'::text THEN 100
            WHEN 'High'::text THEN 75
            WHEN 'Medium'::text THEN 50
            ELSE 25
        END)::numeric * category_weight) / ( SELECT max(cats.category_weight) AS max
           FROM cats)) * rule_weight) / max(rule_weight) OVER (PARTITION BY category_code)), 1) AS rule_risk_score
   FROM r;

